# utils/tenant_reset_alembic.py
#
# Resets the `alembic_version` table on every tenant database.
#
# Usage:
#   python app/utils/tenant_reset_alembic.py                 # clears alembic_version (no revision stamped)
#   python app/utils/tenant_reset_alembic.py <revision_id>   # clears and stamps the given revision
#
# Intended for recovery when tenant DBs drift out of sync with the migration
# history (e.g. a failed autogenerated migration left some tenants partially
# applied). After running, re-run run-tenant_dbupgrade.sh to bring every
# tenant back to head.

import os
import sys
from urllib.parse import quote_plus

from dotenv import load_dotenv
from sqlalchemy import create_engine, text

load_dotenv()

MAIN_DB_URL = os.getenv("SUPER_ADMIN_DATABASE_URL")
POSTGRES_HOST = os.getenv("POSTGRES_HOST", "localhost")
POSTGRES_PORT = os.getenv("POSTGRES_PORT", "5432")
POSTGRES_USER = os.getenv("POSTGRES_USER", "postgres")
POSTGRES_PASSWORD = os.getenv("POSTGRES_PASSWORD", "postgres")


def _tenant_db_url(db_name: str) -> str:
    pwd = quote_plus(POSTGRES_PASSWORD)
    return f"postgresql://{POSTGRES_USER}:{pwd}@{POSTGRES_HOST}:{POSTGRES_PORT}/{db_name}"


def get_all_institutions():
    engine = create_engine(MAIN_DB_URL)
    with engine.connect() as conn:
        result = conn.execute(text("SELECT skid FROM institutions"))
        return [row[0] for row in result]


def reset_alembic_version(db_name: str, target_revision: str | None):
    engine = create_engine(_tenant_db_url(db_name))
    with engine.begin() as conn:
        conn.execute(text("""
            CREATE TABLE IF NOT EXISTS alembic_version (
                version_num VARCHAR(32) NOT NULL,
                CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
            )
        """))
        conn.execute(text("DELETE FROM alembic_version"))
        if target_revision:
            conn.execute(
                text("INSERT INTO alembic_version (version_num) VALUES (:rev)"),
                {"rev": target_revision},
            )


def reset_all_tenants(target_revision: str | None):
    skids = get_all_institutions()
    if not skids:
        print("No tenant institutions found.")
        return

    action = f"stamp -> {target_revision}" if target_revision else "clear (no revision)"
    print(f"Resetting alembic_version on {len(skids)} tenant DB(s) — action: {action}")
    print()

    ok, failed = 0, 0
    for skid in skids:
        db_name = f"eduspyre_{skid}"
        try:
            reset_alembic_version(db_name, target_revision)
            print(f"✅  {db_name}")
            ok += 1
        except Exception as e:
            print(f"❌  {db_name}: {e}")
            failed += 1

    print()
    print(f"Done. {ok} succeeded, {failed} failed.")


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else None
    reset_all_tenants(target)
